#Requires -Version 5.1
<#
.SYNOPSIS
Audits a local Windows Server and writes separate HTML reports.
.DESCRIPTION
Version 0.1.0. Collects configuration evidence without applying remediation.
Includes the recommendation catalog from the supplied CIS PDFs. A subset of
checks is automated; other recommendations are explicitly marked for review.
SQL queries use the current Windows identity and read metadata only.
NVD results are POTENTIAL matches, not confirmed missing patches.
.EXAMPLE
.\Invoke-WindowsServerAudit.ps1 -OutputDirectory C:\AuditReports\Server01
.EXAMPLE
.\Invoke-WindowsServerAudit.ps1 -Profiles Level1,Level2 -SkipOnline
.EXAMPLE
$env:NVD_API_KEY = Read-Host 'NVD API key'
.\Invoke-WindowsServerAudit.ps1 -SkipSqlQueries
#>
[CmdletBinding()]
param(
    [string]$OutputDirectory = (Join-Path (Get-Location) ('ServerAudit-{0}-{1}' -f $env:COMPUTERNAME,(Get-Date -Format 'yyyyMMdd-HHmmss'))),
    [ValidateSet('Level1','Level2','STIG','NextGeneration')]
    [string[]]$Profiles = @('Level1','Level2','STIG','NextGeneration'),
    [switch]$SkipOnline,
    [switch]$SkipSqlQueries,
    [string]$NvdApiKey = $env:NVD_API_KEY,
    [ValidateRange(1,1000)][int]$MaxCvesPerProduct = 200,
    [ValidateRange(1,60)][int]$SqlConnectionTimeout = 5,
    [ValidateRange(1,120)][int]$SqlCommandTimeout = 15
)

$ErrorActionPreference = 'Stop'
if ($env:OS -ne 'Windows_NT') { throw 'Run this script locally on Windows Server.' }
if (-not [Environment]::Is64BitProcess) { throw 'Use 64-bit Windows PowerShell or 64-bit PowerShell.' }
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$principal = New-Object Security.Principal.WindowsPrincipal($identity)
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    throw 'Open PowerShell as administrator, then run the script again.'
}
# Create only a new report folder so an earlier report is never overwritten.
if (Test-Path -LiteralPath $OutputDirectory) { throw 'OutputDirectory already exists. Choose a new report folder.' }
$null = New-Item -ItemType Directory -Path $OutputDirectory
$OutputDirectory = (Resolve-Path -LiteralPath $OutputDirectory).Path
$EvidenceDirectory = Join-Path $OutputDirectory 'Evidence'
$null = New-Item -ItemType Directory -Path $EvidenceDirectory
$script:Diagnostics = New-Object 'System.Collections.Generic.List[object]'
$script:NvdCache = @{}
$script:LastNvdRequest = [datetime]::MinValue
$script:Started = Get-Date
$script:RegistryCache = @{}

function Add-Diagnostic {
    param([string]$Stage,[string]$Message)
    $script:Diagnostics.Add([pscustomobject]@{Stage=$Stage;Message=$Message;Time=(Get-Date).ToString('o')})
    Write-Warning ('{0}: {1}' -f $Stage,$Message)
}

function Write-Json {
    param([object]$Value,[string]$Name)
    ConvertTo-Json -InputObject $Value -Depth 35 | Set-Content -LiteralPath (Join-Path $EvidenceDirectory $Name) -Encoding UTF8
}

function Html {
    param([AllowNull()][object]$Text)
    [System.Net.WebUtility]::HtmlEncode([string]$Text)
}

function New-Finding {
    param([string]$Id,[string]$Title,[string]$Status,[string]$Priority,[string]$Expected,[string]$Observed,[string]$Evidence,[string]$Source)
    [pscustomobject]@{Id=$Id;Title=$Title;Status=$Status;Priority=$Priority;Expected=$Expected;Observed=$Observed;Evidence=$Evidence;Source=$Source}
}

function Write-HtmlReport {
    param([string]$Name,[string]$Title,[string]$Summary,[object[]]$Findings = @(),[string]$ExtraHtml='')
    # Encode every machine-supplied value. Software names, service names, and
    # registry values must never be interpreted as HTML or JavaScript.
    $rows = New-Object Text.StringBuilder
    $rank = @{Fail=0;Review=1;Error=2;NotImplemented=3;Manual=4;Unavailable=5;Pass=6;Info=7}
    $risk = @{Critical=0;High=1;Medium=2;Low=3;Informational=4}
    foreach ($f in @($Findings | Sort-Object @{Expression={$rank[$_.Status]}},@{Expression={$risk[$_.Priority]}},Id)) {
        $null = $rows.Append(('<tr data-status="{0}"><td><span class="badge">{0}</span><br>{1}</td><td><b>{2}</b><br>{3}</td><td>{4}</td><td>{5}</td><td>{6}<br><small>{7}</small></td></tr>' -f
            (Html $f.Status),(Html $f.Priority),(Html $f.Id),(Html $f.Title),(Html $f.Expected),(Html $f.Observed),(Html $f.Evidence),(Html $f.Source)))
    }
    $counts = @($Findings | Group-Object Status | ForEach-Object { '{0}: {1}' -f $_.Name,$_.Count }) -join ' | '
    $html = @"
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src 'none'; connect-src 'none'">
<title>$(Html $Title)</title><style>
:root{font:15px/1.5 Segoe UI,Arial,sans-serif;color:#182c3b;background:#eef3f7}body{margin:0}header{padding:30px 4%;background:#142e42;color:white}header a{color:#b9e5ff}h1{margin:6px 0;font-size:28px}main{padding:24px 4%}section,.notice{background:white;border:1px solid #d0dbe3;border-radius:10px;padding:18px;margin:16px 0}.notice{border-left:5px solid #e8aa33}table{border-collapse:collapse;width:100%;font-size:14px;background:white}th{background:#dbe7ef;text-align:left}td,th{padding:12px;vertical-align:top;border-bottom:1px solid #dbe3e9;overflow-wrap:anywhere}small{color:#526777}tr[data-status=Fail]{border-left:5px solid #b63333}tr[data-status=Review],tr[data-status=Error]{border-left:5px solid #c78015}tr[data-status=Pass]{border-left:5px solid #2e8056}.badge{font-weight:700}input,select{padding:9px;margin:0 8px 12px 0;border:1px solid #a8b9c6;border-radius:5px}a{color:#145d88}.links a{display:inline-block;padding:8px 12px;background:#edf3f8;border-radius:5px;margin:5px}pre{white-space:pre-wrap}footer{padding:20px 4%;color:#526777}@media print{input,select{display:none}header{background:white;color:black}main{padding:0}td,th{padding:6px}}
</style></head><body><header><a href="index.html">Audit overview</a><h1>$(Html $Title)</h1><div>$(Html $script:MachineLabel) | $(Html $script:Started.ToString('o')) | Auditor 0.1.0</div></header><main>
<div class="notice">$(Html $Summary)</div><p>$(Html $counts)</p>$ExtraHtml
<input id="search" type="search" placeholder="Search findings" aria-label="Search findings"><select id="status" aria-label="Filter status"><option value="">All statuses</option><option>Fail</option><option>Review</option><option>Error</option><option>Pass</option><option>Manual</option><option>NotImplemented</option><option>Unavailable</option><option>Info</option></select>
<div style="overflow-x:auto"><table id="findings"><thead><tr><th>Status / priority</th><th>Finding</th><th>Expected</th><th>Observed</th><th>Evidence / source</th></tr></thead><tbody>$rows</tbody></table></div>
</main><footer>Priorities are auditor triage categories, not CIS severities or CVSS scores. Pass means the implemented comparison passed. Review, Manual, NotImplemented, Error and Unavailable are never passes. No complete compliance score is calculated.</footer>
<script>const s=document.getElementById('search'),f=document.getElementById('status');function filter(){const q=s.value.toLowerCase();document.querySelectorAll('#findings tbody tr').forEach(r=>{r.hidden=!(r.textContent.toLowerCase().includes(q)&&(!f.value||r.dataset.status===f.value))})}s.addEventListener('input',filter);f.addEventListener('change',filter);</script></body></html>
"@
    $html | Set-Content -LiteralPath (Join-Path $OutputDirectory $Name) -Encoding UTF8
}

function Get-SecurityPolicyEvidence {
    $policy = @{}
    try {
        $cfg = Join-Path $EvidenceDirectory 'SecurityPolicy.inf'
        $log = Join-Path $EvidenceDirectory 'SecurityPolicyExport.log'
        # /export reads policy into a report file. /configure is never used.
        $null = & "$env:windir\System32\secedit.exe" /export /mergedpolicy /cfg $cfg /areas SECURITYPOLICY /log $log /quiet 2>&1
        if ($LASTEXITCODE -ne 0) { throw "secedit export returned $LASTEXITCODE" }
        foreach ($line in Get-Content -LiteralPath $cfg) {
            if ($line -match '^\s*(\w+)\s*=\s*(-?\d+)\s*$') { $policy[$matches[1]] = [long]$matches[2] }
        }
    } catch { Add-Diagnostic 'Security policy export' $_.Exception.Message }
    return $policy
}

function Test-CatalogControl {
    param([object]$Control,[object]$Benchmark,[hashtable]$SecurityPolicy)
    $status = 'NotImplemented'; $observed = 'No automated evaluator in this version.'; $evidence = ''
    $source = '{0}, PDF page {1}, recommendation {2}' -f $Benchmark.File,$Control.PdfPage,$Control.Id
    if ($Control.Assessment -eq 'Manual') { $status='Manual'; $observed='Requires human validation using the source benchmark.' }
    elseif ($null -ne $Control.Rule) {
        $rule = $Control.Rule
        try {
            switch ($rule.Kind) {
                'RegistryDword' {
                    $evidence = '{0}:{1}; required DWORD={2}' -f $rule.Path,$rule.Name,$rule.Expected
                    $cacheKey = $rule.Path + '|' + $rule.Name
                    if (-not $script:RegistryCache.ContainsKey($cacheKey)) {
                        if (Test-Path -LiteralPath $rule.Path) {
                            $key = Get-Item -LiteralPath $rule.Path
                            try {
                                $names = $key.GetValueNames()
                                if ($names -contains $rule.Name) {
                                    $script:RegistryCache[$cacheKey] = @{Found=$true;Kind=[string]$key.GetValueKind($rule.Name);Value=$key.GetValue($rule.Name)}
                                } else { $script:RegistryCache[$cacheKey] = @{Found=$false} }
                            } finally { $key.Close() }
                        } else { $script:RegistryCache[$cacheKey] = @{Found=$false} }
                    }
                    $actual = $script:RegistryCache[$cacheKey]
                    if (-not $actual.Found) {
                        $status='Review';$observed='Value absent. Effective default and conditional applicability require review.'
                    } elseif ($actual.Kind -ne 'DWord') {
                        $status='Review';$observed='Unexpected registry type: ' + $actual.Kind
                    } else {
                        $observed=[string]$actual.Value
                        $status = if ([long]$actual.Value -eq [long]$rule.Expected) {'Pass'} else {'Fail'}
                    }
                }
                'SecurityPolicy' {
                    $evidence = 'secedit /export /mergedpolicy; ' + $rule.Name + '. Default policy only; per-user fine-grained password policies are not assessed.'
                    if (-not $SecurityPolicy.ContainsKey($rule.Name)) {$status='Review';$observed='Policy value not available in the export.'}
                    else {
                        $value=[long]$SecurityPolicy[$rule.Name];$observed=[string]$value
                        $passed = switch ($rule.Operator) {
                            'Equal' {$value -eq [long]$rule.Expected}
                            'Minimum' {$value -ge [long]$rule.Expected}
                            'Maximum' {$value -ge 0 -and $value -le [long]$rule.Expected}
                            'MaximumNonzero' {$value -gt 0 -and $value -le [long]$rule.Expected}
                            default {throw 'Unknown comparison operator'}
                        }
                        $status = if ($passed) {'Pass'} else {'Fail'}
                    }
                }
                default {throw 'Unknown declarative rule kind'}
            }
        } catch {$status='Error';$observed=$_.Exception.Message}
    }
    if (-not $Control.Expected) { $expected=$Control.Title } else { $expected=$Control.Expected }
    New-Finding $Control.Id $Control.Title $status $Control.Priority $expected $observed $evidence $source
}

function Get-InstalledSoftware {
    $list = New-Object 'System.Collections.Generic.List[object]'
    foreach ($view in @([Microsoft.Win32.RegistryView]::Registry64,[Microsoft.Win32.RegistryView]::Registry32)) {
        $base = $null; $uninstall = $null
        try {
            $base=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,$view)
            $uninstall=$base.OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall')
            if ($null -eq $uninstall) {continue}
            foreach ($name in $uninstall.GetSubKeyNames()) {
                $key=$null
                try {
                    $key=$uninstall.OpenSubKey($name)
                    if ($null -ne $key -and $key.GetValue('DisplayName')) {
                        $list.Add([pscustomobject]@{Name=[string]$key.GetValue('DisplayName');Version=[string]$key.GetValue('DisplayVersion');Publisher=[string]$key.GetValue('Publisher');RegistryView=[string]$view;Scope='Machine uninstall registry'})
                    }
                } catch {Add-Diagnostic 'Software inventory entry' $_.Exception.Message}
                finally {if($key){$key.Close()}}
            }
        } catch {Add-Diagnostic 'Software inventory' $_.Exception.Message}
        finally {if($uninstall){$uninstall.Close()};if($base){$base.Close()}}
    }
    # Win32_Product is intentionally avoided: querying it can trigger MSI repair.
    @($list | Sort-Object Name,Version,RegistryView -Unique)
}

function Invoke-LocalSqlRead {
    param([string]$Instance,[string]$Query)
    $connection=$null;$command=$null;$reader=$null
    try {
        # Shared-memory addressing keeps these connections local. No SQL
        # passwords, impersonation, downloads, or module installation are used.
        $builder=New-Object System.Data.SqlClient.SqlConnectionStringBuilder
        $builder.DataSource=if($Instance -eq 'MSSQLSERVER'){'lpc:.'}else{'lpc:.\'+$Instance}
        $builder.InitialCatalog='master';$builder.IntegratedSecurity=$true
        $builder.ConnectTimeout=$SqlConnectionTimeout;$builder.ApplicationName='WindowsServerAudit ReadOnly'
        $builder.Pooling=$false
        $connection=New-Object System.Data.SqlClient.SqlConnection($builder.ConnectionString)
        $connection.Open();$command=$connection.CreateCommand();$command.CommandTimeout=$SqlCommandTimeout
        $command.CommandText=$Query;$reader=$command.ExecuteReader()
        $result=New-Object 'System.Collections.Generic.List[object]'
        while($reader.Read()) {
            $row=[ordered]@{}
            for($i=0;$i -lt $reader.FieldCount;$i++) {
                $row[$reader.GetName($i)]=if($reader.IsDBNull($i)){$null}else{$reader.GetValue($i)}
            }
            $result.Add([pscustomobject]$row)
        }
        return $result.ToArray()
    } finally {if($reader){$reader.Dispose()};if($command){$command.Dispose()};if($connection){$connection.Dispose()}}
}

function Get-SqlInstances {
    param([object[]]$Services)
    $instances=@{}
    foreach($view in @([Microsoft.Win32.RegistryView]::Registry64,[Microsoft.Win32.RegistryView]::Registry32)) {
        $base=$null;$mapping=$null
        try {
            $base=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,$view)
            $mapping=$base.OpenSubKey('SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL')
            if($null -eq $mapping){continue}
            foreach($instance in $mapping.GetValueNames()) {
                if($instances.ContainsKey($instance)){continue}
                $instanceId=[string]$mapping.GetValue($instance);$setup=$null
                $record=[pscustomobject]@{Instance=$instance;InstanceId=$instanceId;ProductVersion='';Edition='';ProductLevel='';ProductUpdateLevel='';ProductUpdateReference='';VersionSource='Registry setup';ServiceState='Unknown';ServiceAccount='';QueryStatus='Not attempted';QueryError='';RegistryView=[string]$view;Configuration=@();DatabaseFlags=@();DatabaseVisibility='Not assessed'}
                try {
                    $setup=$base.OpenSubKey('SOFTWARE\Microsoft\Microsoft SQL Server\'+$instanceId+'\Setup')
                    if($setup){$record.ProductVersion=[string]$setup.GetValue('Version');$record.Edition=[string]$setup.GetValue('Edition');$record.ProductLevel=[string]$setup.GetValue('SP')}
                } finally {if($setup){$setup.Close()}}
                $instances[$instance]=$record
            }
        } catch {Add-Diagnostic 'SQL instance registry discovery' $_.Exception.Message}
        finally {if($mapping){$mapping.Close()};if($base){$base.Close()}}
    }
    # Include engine services even when an instance registry mapping was missing.
    foreach($service in @($Services | Where-Object {$_.Name -eq 'MSSQLSERVER' -or $_.Name -like 'MSSQL$*'})) {
        $instance=if($service.Name -eq 'MSSQLSERVER'){'MSSQLSERVER'}else{$service.Name.Substring(6)}
        if(-not $instances.ContainsKey($instance)) {
            $instances[$instance]=[pscustomobject]@{Instance=$instance;InstanceId='';ProductVersion='';Edition='';ProductLevel='';ProductUpdateLevel='';ProductUpdateReference='';VersionSource='Unavailable';ServiceState='Unknown';ServiceAccount='';QueryStatus='Not attempted';QueryError='';RegistryView='Service discovery';Configuration=@();DatabaseFlags=@();DatabaseVisibility='Not assessed'}
        }
        $instances[$instance].ServiceState=$service.State;$instances[$instance].ServiceAccount=$service.StartName
    }
    foreach($record in @($instances.Values | Sort-Object Instance)) {
        if($SkipSqlQueries){$record.QueryStatus='Skipped';$record.QueryError='-SkipSqlQueries selected'}
        elseif($record.ServiceState -ne 'Running'){$record.QueryStatus='Unavailable';$record.QueryError='Engine is not running or service state is unavailable. No service was started.'}
        else {
            try {
                $query="SELECT CONVERT(nvarchar(128),SERVERPROPERTY('ProductVersion')) AS ProductVersion, CONVERT(nvarchar(128),SERVERPROPERTY('Edition')) AS Edition, CONVERT(nvarchar(128),SERVERPROPERTY('ProductLevel')) AS ProductLevel, CONVERT(nvarchar(128),SERVERPROPERTY('ProductUpdateLevel')) AS ProductUpdateLevel, CONVERT(nvarchar(128),SERVERPROPERTY('ProductUpdateReference')) AS ProductUpdateReference;"
                $version=@(Invoke-LocalSqlRead $record.Instance $query)
                if($version.Count -ne 1){throw 'SQL version query returned an unexpected number of rows.'}
                foreach($field in @('ProductVersion','Edition','ProductLevel','ProductUpdateLevel','ProductUpdateReference')){$record.$field=[string]$version[0].$field}
                $record.VersionSource='SERVERPROPERTY, current Windows identity';$record.QueryStatus='Version read'
            } catch {$record.QueryStatus='Unavailable';$record.QueryError=$_.Exception.Message}
            if($record.QueryStatus -eq 'Version read') {
                try {
                    $record.Configuration=@(Invoke-LocalSqlRead $record.Instance "SELECT name, CONVERT(int,value_in_use) AS ValueInUse FROM sys.configurations WHERE name IN ('xp_cmdshell','Ole Automation Procedures','Ad Hoc Distributed Queries','cross db ownership chaining','remote admin connections','clr enabled');")
                    $record.QueryStatus='Metadata read'
                } catch {$record.QueryError+=' Configuration query: '+$_.Exception.Message}
                try {
                    $access=@(Invoke-LocalSqlRead $record.Instance "SELECT HAS_PERMS_BY_NAME(NULL,NULL,'VIEW ANY DATABASE') AS CanViewAll;")
                    $record.DatabaseVisibility=if($access.Count -eq 1 -and $access[0].CanViewAll -eq 1){'VIEW ANY DATABASE present; offline or inaccessible databases may still need review'}else{'Limited metadata visibility; inventory may be incomplete'}
                    $record.DatabaseFlags=@(Invoke-LocalSqlRead $record.Instance 'SELECT name, is_trustworthy_on AS Trustworthy, is_db_chaining_on AS Chaining FROM sys.databases WHERE database_id > 4;')
                } catch {$record.QueryError+=' Database metadata query: '+$_.Exception.Message}
            }
        }
        $record
    }
}

function Invoke-NvdLookup {
    param([string]$Cpe)
    if($script:NvdCache.ContainsKey($Cpe)){return $script:NvdCache[$Cpe]}
    $result=[pscustomobject]@{Cpe=$Cpe;Status='Not assessed';Total=0;Truncated=$false;Retrieved='';Error='';Vulnerabilities=@()}
    if($SkipOnline){$result.Status='Skipped';$script:NvdCache[$Cpe]=$result;return $result}
    try {
        # Respect the public API's request spacing; an API key stays in a header
        # and is never written to the report, evidence files, or URL.
        $delay=if($NvdApiKey){0.7}else{6.5}
        $elapsed=((Get-Date)-$script:LastNvdRequest).TotalSeconds
        if($elapsed -lt $delay){Start-Sleep -Milliseconds ([int](1000*($delay-$elapsed)))}
        $headers=@{};if($NvdApiKey){$headers['apiKey']=$NvdApiKey}
        $limit=[Math]::Min($MaxCvesPerProduct,1000)
        $uri='https://services.nvd.nist.gov/rest/json/cves/2.0?virtualMatchString='+[uri]::EscapeDataString($Cpe)+'&resultsPerPage='+$limit
        $script:LastNvdRequest=Get-Date
        $response=Invoke-RestMethod -Uri $uri -Headers $headers -TimeoutSec 45 -Method Get
        if($null -eq $response.totalResults){throw 'NVD returned an unexpected response schema.'}
        $result.Status='Retrieved';$result.Total=[int]$response.totalResults
        $result.Truncated=$result.Total -gt @($response.vulnerabilities).Count
        $result.Retrieved=(Get-Date).ToUniversalTime().ToString('o')
        $result.Vulnerabilities=@($response.vulnerabilities)
    } catch {$result.Status='Unavailable';$result.Error=$_.Exception.Message;Add-Diagnostic 'NVD lookup' ('Lookup failed for '+$Cpe+'. '+$result.Error)}
    $script:NvdCache[$Cpe]=$result
    return $result
}

function Get-CveFindings {
    param([string]$Product,[string]$Cpe,[string]$MatchExplanation,[hashtable]$Kev)
    $lookup=Invoke-NvdLookup $Cpe
    if($lookup.Status -ne 'Retrieved') {
        New-Finding ('CVE lookup: '+$Product) 'Vulnerability lookup incomplete' 'Unavailable' 'Informational' 'Current vulnerability data' $lookup.Status $lookup.Error 'NVD API 2.0'
        return
    }
    if($lookup.Truncated) {
        New-Finding ('CVE coverage: '+$Product) 'CVE candidate results truncated' 'Review' 'High' 'Review the complete product result set' ('Returned '+$lookup.Vulnerabilities.Count+' of '+$lookup.Total) 'The returned page is not guaranteed to contain the most severe or newest candidates. Increase -MaxCvesPerProduct or use a vulnerability platform.' 'NVD API 2.0'
    }
    if($lookup.Total -eq 0) {
        New-Finding ('CVE lookup: '+$Product) 'No CVE candidates returned by this query' 'Info' 'Informational' 'Exact applicability assessment' 'No candidates; this does not establish that the product is free of vulnerabilities.' $Cpe ('NVD retrieved '+$lookup.Retrieved)
    }
    foreach($entry in $lookup.Vulnerabilities) {
        $cve=$entry.cve
        if($cve.vulnStatus -eq 'Rejected'){continue}
        $description=@($cve.descriptions | Where-Object {$_.lang -eq 'en'} | Select-Object -First 1)
        $text=if($description.Count){[string]$description[0].value}else{'No English description available'}
        $score='Not available'
        foreach($metric in @('cvssMetricV40','cvssMetricV31','cvssMetricV30','cvssMetricV2')) {
            if($null -ne $cve.metrics) {
                $property=$cve.metrics.PSObject.Properties[$metric]
                if($property -and @($property.Value).Count){$metricValues=@($property.Value);$score=[string]$metricValues[0].cvssData.baseScore;break}
            }
        }
        $known=if($Kev.ContainsKey([string]$cve.id)){'Listed in CISA KEV; applicability to this installation still requires validation.'}else{'No KEV match in the retrieved feed, or feed unavailable.'}
        $priority=if($Kev.ContainsKey([string]$cve.id)){'High'}else{'Medium'}
        New-Finding ([string]$cve.id) ($Product+': '+$text) 'Review' $priority 'Validate installed build, update branch, components, prerequisites and vendor advisory.' ('Potential match only. Published CVSS: '+$score+'. '+$known) ($MatchExplanation+' Query='+$Cpe) ('https://nvd.nist.gov/vuln/detail/'+$cve.id+'; retrieved '+$lookup.Retrieved)
    }
}

# The embedded data is a compressed declarative catalog, not executable code.
# It is generated from the uploaded benchmark PDFs with source hashes and pages.
$catalogCompressed = ''
$stream=New-Object IO.MemoryStream -ArgumentList (,[Convert]::FromBase64String($catalogCompressed))
$gzip=New-Object IO.Compression.GZipStream($stream,[IO.Compression.CompressionMode]::Decompress)
$reader=New-Object IO.StreamReader($gzip,[Text.Encoding]::UTF8)
try {$catalog=$reader.ReadToEnd() | ConvertFrom-Json} finally {$reader.Dispose();$gzip.Dispose();$stream.Dispose()}

Write-Host 'Collecting Windows Server identity and local configuration...'
$os=Get-CimInstance Win32_OperatingSystem
if([int]$os.ProductType -eq 1){throw 'This script supports Windows Server, not Windows desktop editions.'}
$computer=Get-CimInstance Win32_ComputerSystem
$buildMap=@{'14393'='2016';'17763'='2019';'20348'='2022';'26100'='2025'}
$year=$buildMap[[string]$os.BuildNumber]
if(-not $year){throw ('Unsupported Windows Server build: '+$os.BuildNumber)}
$role=if([int]$computer.DomainRole -in @(4,5)){'Domain Controller'}elseif($computer.PartOfDomain){'Member Server'}else{'Standalone'}
$flavor=if($role -eq 'Standalone'){'Standalone'}else{'Domain'}
$auditProfileRole=if($role -eq 'Domain Controller'){'Domain Controller'}else{'Member Server'}
$script:MachineLabel=$env:COMPUTERNAME+' | Windows Server '+$year+' | '+$role
$ubr=Get-ItemPropertyValue -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -Name UBR -ErrorAction SilentlyContinue
$machine=[pscustomobject]@{Computer=$env:COMPUTERNAME;Caption=$os.Caption;Year=$year;Build=([string]$os.BuildNumber+'.'+[string]$ubr);Role=$role;PartOfDomain=$computer.PartOfDomain;Domain=$computer.Domain;AuditVersion='0.1.0';Started=$script:Started.ToString('o')}
Write-Json $machine 'Machine.json'
$policy=Get-SecurityPolicyEvidence
$services=@();try{$services=@(Get-CimInstance Win32_Service)}catch{Add-Diagnostic 'Service inventory' $_.Exception.Message}
Write-Json @($services | Select-Object Name,DisplayName,State,StartMode,StartName,PathName) 'Services.json'
try {Write-Json @(Get-NetTCPConnection -State Listen | Select-Object LocalAddress,LocalPort,OwningProcess) 'ListeningPorts.json'}catch{Add-Diagnostic 'Listening ports' $_.Exception.Message}
$firewallProfiles=@()
try {$firewallProfiles=@(Get-NetFirewallProfile -PolicyStore ActiveStore | Select-Object Name,Enabled,DefaultInboundAction,DefaultOutboundAction);Write-Json $firewallProfiles 'EffectiveFirewallProfiles.json'}catch{Add-Diagnostic 'Firewall inventory' $_.Exception.Message}
try {Write-Json @(Get-HotFix | Select-Object HotFixID,Description,InstalledOn) 'InstalledHotfixes.json'}catch{Add-Diagnostic 'Installed hotfix inventory' $_.Exception.Message}

$links=New-Object Text.StringBuilder
$overview=New-Object 'System.Collections.Generic.List[object]'
$benchmarkResults=@{}
foreach($auditProfile in @($Profiles | Select-Object -Unique)) {
    Write-Host ('Assessing '+$auditProfile+'...')
    $requiredFlavor=if($auditProfile -eq 'STIG'){'STIG'}else{$flavor}
    $benchmarks=@($catalog.Benchmarks | Where-Object {$_.Year -eq $year -and $_.Flavor -eq $requiredFlavor})
    $file=$auditProfile+'.html';$findings=@()
    $summary='Partial automated assessment. Single DWORD comparisons and selected account policy settings are implemented. Other controls remain visible for review. Registry checks establish configured values; they do not prove every runtime dependency or policy delivery mechanism. No direct configuration-to-CVE mapping is asserted; see Software.html for potential product CVEs.'
    if($benchmarks.Count -ne 1 -or ($auditProfile -eq 'STIG' -and $role -eq 'Standalone')) {
        $findings=@(New-Finding $auditProfile 'Matching benchmark unavailable' 'Unavailable' 'Informational' ($year+' '+$role+' '+$auditProfile) 'No applicable source benchmark supplied.' 'The script does not substitute another OS, role, or benchmark edition.' 'Supplied benchmark catalog')
    } else {
        $benchmark=$benchmarks[0]
        $wanted=switch($auditProfile){'Level1'{@('Level 1 - '+$auditProfileRole)}'Level2'{@(('Level 1 - '+$auditProfileRole),('Level 2 - '+$auditProfileRole))}'STIG'{@('STIG '+$auditProfileRole)}'NextGeneration'{@('Next Generation Windows Security - '+$auditProfileRole)}}
        $controls=@($benchmark.Controls | Where-Object {$cp=$_.Profiles; @($wanted | Where-Object {$cp -contains $_}).Count -gt 0})
        foreach($control in $controls) {
            $cacheKey=$benchmark.File+'|'+$control.Id
            if(-not $benchmarkResults.ContainsKey($cacheKey)){$benchmarkResults[$cacheKey]=Test-CatalogControl $control $benchmark $policy}
            $findings+= $benchmarkResults[$cacheKey]
        }
        $summary+=' Source: '+$benchmark.File+'. Source SHA256: '+$benchmark.Sha256+'.'
        if($auditProfile -eq 'NextGeneration'){$summary+=' This report covers only the optional advanced profile; it is not a full Level 1 or Level 2 assessment.'}
        if(-not $controls.Count){$findings=@(New-Finding $auditProfile 'No controls matched the selected profile' 'Error' 'High' 'Applicable controls' 'Catalog/profile selection needs investigation.' '' $benchmark.File)}
    }
    Write-HtmlReport $file ($auditProfile+' configuration audit') $summary $findings
    Write-Json @($findings) ($auditProfile+'.json')
    $null=$links.Append(('<a href="{0}">{1}</a>' -f $file,(Html $auditProfile)))
    $passes=@($findings | Where-Object Status -eq 'Pass').Count;$fails=@($findings | Where-Object Status -eq 'Fail').Count
    $overview.Add((New-Finding $auditProfile ($auditProfile+' report') 'Info' 'Informational' 'Review failures and assessment coverage.' ('Pass='+$passes+'; Fail='+$fails+'; Other='+($findings.Count-$passes-$fails)) ($findings.Count.ToString()+' report entries. Other statuses are not passes.') $file))
}

Write-Host 'Discovering installed software and Microsoft SQL Server instances...'
Add-Type -AssemblyName System.Data
$software=@(Get-InstalledSoftware);Write-Json $software 'InstalledSoftware.json'
$sql=@(Get-SqlInstances $services);Write-Json $sql 'SqlInstances.json'
$sqlFindings=New-Object 'System.Collections.Generic.List[object]'
foreach($instance in $sql) {
    $sqlFindings.Add((New-Finding $instance.Instance 'Microsoft SQL Server engine instance' 'Info' 'Informational' 'Record exact instance build and CU/GDR branch.' ($instance.ProductVersion+' | '+$instance.Edition+' | '+$instance.ProductLevel+' | '+$instance.ProductUpdateLevel+' | '+$instance.ProductUpdateReference) ('Service='+$instance.ServiceState+'; Account='+$instance.ServiceAccount+'; Source='+$instance.VersionSource) 'Local registry / SERVERPROPERTY'))
    if($instance.QueryError -or $instance.QueryStatus -ne 'Metadata read') {
        $sqlFindings.Add((New-Finding $instance.Instance 'SQL metadata assessment incomplete' 'Unavailable' 'Informational' 'Metadata readable by the audit identity.' $instance.QueryStatus $instance.QueryError 'Local SQL metadata queries'))
    }
    foreach($setting in $instance.Configuration) {
        $sqlFindings.Add((New-Finding ($instance.Instance+'/'+$setting.name) 'SQL Server feature configuration requires context' 'Review' 'Medium' 'Confirm this feature is required and approved for the workload.' ([string]$setting.ValueInUse) 'Supplemental observation. A value of 1 means enabled; this is not an assessed CIS database recommendation.' 'sys.configurations'))
    }
    foreach($database in $instance.DatabaseFlags) {
        if($database.Trustworthy -eq 1 -or $database.Chaining -eq 1) {
            $sqlFindings.Add((New-Finding ($instance.Instance+'/'+$database.name) 'Database trust or ownership chaining enabled' 'Review' 'High' 'Validate business requirement, ownership and permissions.' ('TRUSTWORTHY='+$database.Trustworthy+'; DB_CHAINING='+$database.Chaining) $instance.DatabaseVisibility 'sys.databases; supplemental observation, no database CIS benchmark supplied'))
        }
    }
    $sqlFindings.Add((New-Finding ($instance.Instance+'/coverage') 'Database configuration benchmark not supplied' 'NotImplemented' 'Informational' 'Version-specific SQL Server CIS benchmark.' $instance.DatabaseVisibility 'Only selected metadata observations are collected in this release. Database contents are not read.' 'Assessment coverage'))
}
if(-not $sql.Count){$sqlFindings.Add((New-Finding 'SQL discovery' 'No SQL Server engine instance discovered' 'Info' 'Informational' 'Local registry and engine service discovery.' 'No mapped instances or engine services found.' 'Does not inventory remote SQL hosts, containers, LocalDB, SSAS or SSRS.' 'Local discovery'))}
Write-HtmlReport 'SQLServer.html' 'Microsoft SQL Server instances' 'Each local Database Engine instance is assessed separately. Queries use the current Windows identity over local shared memory. Selected metadata observations are supplemental and are not a complete SQL Server CIS assessment.' $sqlFindings.ToArray()
Write-Json $sqlFindings.ToArray() 'SqlFindings.json'

$kev=@{};$kevStatus='Not retrieved'
if(-not $SkipOnline) {
    try {
        $feed=Invoke-RestMethod -Uri 'https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json' -TimeoutSec 30
        if($null -eq $feed.vulnerabilities -or -not $feed.catalogVersion){throw 'CISA returned an unexpected response schema.'}
        foreach($v in $feed.vulnerabilities){$kev[[string]$v.cveID]=$true}
        $kevStatus='Retrieved '+(Get-Date).ToUniversalTime().ToString('o');Write-Json $feed 'CisaKev.json'
    } catch {$kevStatus='Unavailable';Add-Diagnostic 'CISA KEV' $_.Exception.Message}
}
Write-Host 'Assessing potential CVE matches (public API requests may take several minutes)...'
$cveFindings=New-Object 'System.Collections.Generic.List[object]'
$productQueries=@{}
$sqlYears=@{'10'='2008';'11'='2012';'12'='2014';'13'='2016';'14'='2017';'15'='2019';'16'='2022';'17'='2025'}
foreach($instance in $sql) {
    $major=($instance.ProductVersion -split '\.')[0];$sqlYear=$sqlYears[$major]
    if($major -eq '10' -and $instance.ProductVersion -like '10.5*'){$sqlYear='2008_r2'}
    if($sqlYear) {
        $cpe='cpe:2.3:a:microsoft:sql_server:'+ $sqlYear
        $explanation='SQL release-family candidates only. Installed build='+$instance.ProductVersion+'; instance='+$instance.Instance+'. CU/GDR branch and fixed-build applicability are NOT resolved.'
        foreach($f in @(Get-CveFindings ('SQL Server '+$sqlYear+' / '+$instance.Instance) $cpe $explanation $kev)){$cveFindings.Add($f)}
    } else {
        $cveFindings.Add((New-Finding $instance.Instance 'SQL product version could not be mapped' 'Unavailable' 'Informational' 'Supported SQL release and exact build.' $instance.ProductVersion 'No SQL CVE lookup performed for this instance.' 'Local discovery'))
    }
}
foreach($app in $software) {
    $product=$null
    if($app.Publisher -match 'Google' -and $app.Name -eq 'Google Chrome'){$product='google:chrome'}
    elseif($app.Publisher -match 'Mozilla' -and $app.Name -match '^Mozilla Firefox'){$product='mozilla:firefox'}
    elseif($app.Publisher -match 'Igor Pavlov' -and $app.Name -match '^7-Zip'){$product='7-zip:7-zip'}
    if($product -and $app.Version -match '^\d+(\.\d+){1,3}$') {
        $cpe='cpe:2.3:a:'+ $product+':'+$app.Version
        if(-not $productQueries.ContainsKey($cpe)){
            $productQueries[$cpe]=$true
            foreach($f in @(Get-CveFindings ($app.Name+' '+$app.Version) $cpe 'Product/version candidate; validate platform, component and vendor prerequisites.' $kev)){$cveFindings.Add($f)}
        }
    }
}
$cveFindings.Add((New-Finding 'Windows patch coverage' 'Windows missing-patch applicability is not implemented' 'NotImplemented' 'High' 'Vendor patch applicability with supersedence and build validation.' $machine.Build 'Installed hotfix inventory is saved as evidence. No missing-patch conclusions are drawn from that inventory.' 'Assessment coverage'))
$cveFindings.Add((New-Finding 'Software coverage' 'Software inventory is broader than CVE matching coverage' 'Info' 'Informational' 'Review products without a supported mapping.' ($software.Count.ToString()+' machine uninstall entries inventoried.') 'CVE lookups support SQL Server release families, Google Chrome, Mozilla Firefox and 7-Zip. Portable apps, per-user apps, dependencies, containers and other products are not assessed for CVEs.' ('CISA KEV: '+$kevStatus)))
Write-HtmlReport 'Software.html' 'Software and potential CVE matches' 'Every CVE shown is a candidate requiring review, not a confirmed vulnerability on this host. SQL release-family queries do not establish missing security updates. A lookup failure, truncated page or zero results never proves a product safe. No installed software inventory is uploaded as a file; supported product identifiers are sent to NVD.' $cveFindings.ToArray()
Write-Json $cveFindings.ToArray() 'CveFindings.json'
Write-Json @($script:NvdCache.Values) 'NvdResponses.json'
$inventoryRows=@($software | ForEach-Object {New-Finding $_.Name 'Installed machine software' 'Info' 'Informational' '' $_.Version ($_.Publisher+' | '+$_.RegistryView) $_.Scope})
Write-HtmlReport 'Inventory.html' 'Installed software inventory' 'Machine-wide uninstall registry entries from both registry views. This inventory does not establish that every executable, per-user installation, dependency or container has been discovered.' $inventoryRows
$null=$links.Append('<a href="SQLServer.html">SQL Server instances</a><a href="Software.html">Software / CVE candidates</a><a href="Inventory.html">Software inventory</a>')
Write-Json $script:Diagnostics.ToArray() 'Diagnostics.json'
foreach($diagnostic in $script:Diagnostics){$overview.Add((New-Finding $diagnostic.Stage 'Evidence collection warning' 'Error' 'Informational' 'Successful evidence collection.' $diagnostic.Message $diagnostic.Time 'Diagnostics.json'))}
# Bring actionable configuration failures to the overview, deduplicating shared
# Level 1/Level 2 controls. Unknown and candidate findings retain their status.
$triageRanks=@{Critical=0;High=1;Medium=2;Low=3;Informational=4}
foreach($f in @($benchmarkResults.Values | Where-Object Status -eq 'Fail' | Sort-Object @{Expression={$triageRanks[$_.Priority]}},Id | Select-Object -First 30)){$overview.Add($f)}
foreach($f in @($sqlFindings | Where-Object {$_.Status -eq 'Review' -and $_.Priority -eq 'High'})){$overview.Add($f)}
foreach($fp in $firewallProfiles) {
    if([string]$fp.Enabled -eq 'False') {
        $overview.Add((New-Finding ('Firewall/'+$fp.Name) 'Windows Firewall profile is disabled in the active policy store' 'Fail' 'High' 'Review firewall protection and approved exceptions.' ([string]$fp.Enabled) 'This profile may be inactive on current network interfaces. Network reachability is not tested.' 'Get-NetFirewallProfile -PolicyStore ActiveStore; supplemental check'))
    }
}
$summary='Audit-only prototype with partial automation. Up to 30 configuration failures, selected SQL observations, and firewall findings appear below. Open each report to review all failures, unknowns and coverage. No complete CIS compliance score or confirmed vulnerability count is produced. SQL security configuration requires its own version-specific benchmark for a full audit.'
$extra='<section class="links">'+$links.ToString()+'</section><section><b>Evidence and coverage</b><p>Evidence JSON files and policy exports are in the Evidence folder. Reports are self-contained and make no network requests when opened. The scan reads configuration and selected SQL metadata, writes report/evidence files, and makes public vulnerability-data requests unless -SkipOnline was selected. Normal Windows and SQL connection/audit logging may record these reads.</p><p>Computer: '+(Html $machine.Computer)+' | Build: '+(Html $machine.Build)+' | Role: '+(Html $role)+'</p></section>'
Write-HtmlReport 'index.html' 'Windows Server security audit' $summary $overview.ToArray() $extra
Write-Host ('Reports saved to '+(Join-Path $OutputDirectory 'index.html'))
[pscustomobject]@{Report=(Join-Path $OutputDirectory 'index.html');Computer=$env:COMPUTERNAME;WindowsServer=$year;Role=$role;SqlInstances=$sql.Count;Warnings=$script:Diagnostics.Count}
